const fs = require('fs');
const RISCOS = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\riscos.md';
const ALERTAS = 'C:\\Users\\usuario\\Desktop\\Projeto-professor-William\\auditoria\\alertas-automaticos.md';
const LIMITE_DIAS = 5;

const content = fs.readFileSync(RISCOS, 'utf8');
const lines = content.split(/\r?\n/);
const hoje = new Date(); hoje.setUTCHours(0,0,0,0);

const parados = [];
for (const line of lines) {
  const t = line.trim();
  if (!t.startsWith('|')) continue;
  const cells = t.split('|').slice(1, -1).map(c => c.trim());
  if (cells.length !== 11) continue;
  const [num, risco, categoria, , , severidade, responsavel, , , status, desde] = cells;
  if (!/^\d+$/.test(num)) continue;
  if (!status.includes('\u23F3')) continue; // so os ⏳ (aberto/parcial), nao os ✅
  const m = desde.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (!m) continue;
  const d = new Date(Date.UTC(+m[1], +m[2]-1, +m[3]));
  const diasParado = Math.round((hoje - d) / 86400000);
  if (diasParado >= LIMITE_DIAS) {
    parados.push({ num, risco: risco.slice(0, 90), categoria, severidade: severidade.replace(/\*\*/g,''), responsavel, diasParado });
  }
}
parados.sort((a, b) => b.diasParado - a.diasParado);

const agora = new Date();
const pad = n => String(n).padStart(2, '0');
const dataStr = `${agora.getUTCFullYear()}-${pad(agora.getUTCMonth()+1)}-${pad(agora.getUTCDate())}`;
const horaStr = `${pad(agora.getUTCHours())}:${pad(agora.getUTCMinutes())}`;

let bloco = `\n## ${dataStr} ${horaStr} — n8n (automático, Risco Parado)\n\n`;
if (parados.length === 0) {
  bloco += `Nenhum risco aberto há ${LIMITE_DIAS}+ dias sem mitigação completa.\n`;
} else {
  bloco += `${parados.length} risco(s) aberto(s) há ${LIMITE_DIAS}+ dias sem mitigação completa:\n\n`;
  for (const p of parados) {
    bloco += `- Risco #${p.num} [${p.categoria}, severidade ${p.severidade}] (${p.diasParado}d parado, responsável ${p.responsavel}): ${p.risco}\n`;
  }
}

if (!fs.existsSync(ALERTAS)) {
  fs.writeFileSync(ALERTAS, '# Alertas automáticos — n8n\n\nLido pelo Diretor no início de toda sessão, junto com o resto de auditoria/.\n' + bloco, 'utf8');
} else {
  fs.appendFileSync(ALERTAS, bloco, 'utf8');
}

return [{ json: { parados: parados.length, detalhe: parados } }];
